import {
  component$,
  createContextId,
  Slot,
  useContext,
  useContextProvider,
  useSignal,
  useVisibleTask$,
  type Signal,
} from "@builder.io/qwik";
import type posthog from "posthog-js";
import { useAuth } from "./auth-context";
import {
  FALLBACK_FEATURES,
  POSTHOG_FEATURE_FLAG_KEYS,
  setRuntimeFeatures,
  type FeatureFlags,
} from "./feature-flags";
import { buildPostHogInitOptions } from "./posthog-config";

interface FeatureFlagState {
  flags: FeatureFlags;
  loaded: boolean;
  configured: boolean;
  error?: string;
}

type PostHogClient = typeof posthog;

export const FeatureFlagContext = createContextId<Signal<FeatureFlagState>>(
  "twyne.feature-flags",
);

let clientPromise: Promise<PostHogClient | null> | null = null;
let initialized = false;

function posthogConfig(): {
  key: string;
  host: string;
  capture: boolean;
} | null {
  const key = import.meta.env.PUBLIC_POSTHOG_KEY as string | undefined;
  if (!key) return null;
  return {
    key,
    host:
      (import.meta.env.PUBLIC_POSTHOG_HOST as string | undefined) ??
      "https://us.i.posthog.com",
    capture: import.meta.env.PUBLIC_POSTHOG_CAPTURE !== "false",
  };
}

async function getPostHogClient(): Promise<PostHogClient | null> {
  if (typeof window === "undefined") return null;
  const config = posthogConfig();
  if (!config) return null;

  clientPromise ??= import("posthog-js").then((mod) => {
    const client = mod.default;
    if (!initialized) {
      client.init(
        config.key,
        buildPostHogInitOptions({
          host: config.host,
          capture: config.capture,
          flagKeys: Object.values(POSTHOG_FEATURE_FLAG_KEYS),
        }),
      );
      initialized = true;
    }
    return client;
  });

  return clientPromise;
}

export async function capturePostHogEvent(
  event: string,
  properties: Record<string, unknown>,
): Promise<void> {
  const client = await getPostHogClient();
  if (!client) return;
  client.capture(event, properties);
}

function readFlags(client: PostHogClient): FeatureFlags {
  return {
    pricing:
      client.isFeatureEnabled(POSTHOG_FEATURE_FLAG_KEYS.pricing) ??
      FALLBACK_FEATURES.pricing,
    localAi:
      client.isFeatureEnabled(POSTHOG_FEATURE_FLAG_KEYS.localAi) ??
      FALLBACK_FEATURES.localAi,
  };
}

export function useFeatureFlags(): Signal<FeatureFlagState> {
  return useContext(FeatureFlagContext);
}

export const PostHogProvider = component$(() => {
  const flags = useSignal<FeatureFlagState>({
    flags: FALLBACK_FEATURES,
    loaded: !posthogConfig(),
    configured: !!posthogConfig(),
  });
  const auth = useAuth();

  useContextProvider(FeatureFlagContext, flags);

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(async ({ cleanup }) => {
    const client = await getPostHogClient();
    if (!client) {
      setRuntimeFeatures(FALLBACK_FEATURES);
      flags.value = {
        flags: FALLBACK_FEATURES,
        loaded: true,
        configured: false,
      };
      return;
    }

    const apply = (next: FeatureFlags, error?: string) => {
      setRuntimeFeatures(next);
      flags.value = {
        flags: next,
        loaded: true,
        configured: true,
        error,
      };
    };

    const unsubscribe = client.onFeatureFlags((_keys, _variants, meta) => {
      const next = meta?.errorsLoading ? FALLBACK_FEATURES : readFlags(client);
      apply(
        next,
        meta?.errorsLoading
          ? "PostHog feature flags failed to load"
          : undefined,
      );
    });

    const cached = readFlags(client);
    apply(cached);

    if (typeof unsubscribe === "function") {
      cleanup(unsubscribe);
    }
  });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(async ({ track }) => {
    track(() => auth.value.user?.id);
    track(() => auth.value.user?.email);
    track(() => auth.value.user?.name);
    track(() => auth.value.loading);
    track(() => auth.value.provider);

    const client = await getPostHogClient();
    if (!client || auth.value.loading) return;

    if (auth.value.user) {
      const previousUserId = client.get_property("$user_id");
      if (previousUserId && previousUserId !== auth.value.user.id) {
        client.reset();
      }
      client.identify(auth.value.user.id, {
        email: auth.value.user.email,
        name: auth.value.user.name,
        auth_provider: auth.value.provider,
      });

      if (previousUserId !== auth.value.user.id) {
        client.capture("sign_in_completed", {
          analytics_version: 1,
          provider: auth.value.provider ?? "convex",
        });
      }
    } else if (client.get_property("$user_id")) {
      // `reset()` creates a fresh anonymous id. Only do that when an
      // identified session actually ended; resetting every anonymous page
      // load made the same returning writer look like a brand-new person.
      client.reset();
    }
  });

  return <Slot />;
});
import type { AiProviderType } from "../types";
import {
  APP_ERROR_CODES,
  type AppErrorCode,
} from "../types/application-errors";
import { capturePostHogEvent } from "./posthog-context";

export const ANALYTICS_VERSION = 1 as const;

export type LandingCtaLocation = "header" | "hero" | "mid_page" | "footer";
export type LandingCtaDestination =
  | "onboarding"
  | "dossier"
  | "editor"
  | "pricing"
  | "sign_in"
  | "downloads";
export type SignInMethod = "passkey" | "email_otp" | "bluesky";
export type SignInProvider = "convex" | "atproto";
export type FolioAnalyticsSource =
  | "landing"
  | "editor"
  | "onboarding"
  | "import"
  | "sync"
  | "integration";
export type AnalyticsFolioType = "draft" | "notes" | "outline";
export type DraftMilestone =
  | "first_edit"
  | "100_words"
  | "500_words"
  | "1000_words"
  | "2500_words";
export type WordCountBucket =
  | "empty"
  | "1_99"
  | "100_499"
  | "500_999"
  | "1000_2499"
  | "2500_plus";
export type EditorialAction =
  | "persona_feedback"
  | "persona_reply"
  | "persona_rewrite"
  | "persona_analysis"
  | "room_synthesis"
  | "rubric_review"
  | "dossier_check"
  | "research";
export type EditorialActionSource =
  | "editor"
  | "dossier"
  | "analysis"
  | "background";
export type DraftExportFormat =
  | "pdf"
  | "markdown"
  | "html"
  | "txt"
  | "twyne_backup";
export type DraftPublishDestination =
  | "twyne_share"
  | "twyne_blog"
  | "atproto"
  | "standard_site";
export type DossierMode = "first_run" | "refine";
export type AnalyticsAiProvider = AiProviderType | "hosted" | "none";

export interface ProductAnalyticsEventMap {
  landing_cta_clicked: {
    location: LandingCtaLocation;
    destination: LandingCtaDestination;
  };
  sign_in_started: { method: SignInMethod };
  sign_in_completed: { provider: SignInProvider };
  sign_in_failed: { method: SignInMethod; error_code: AppErrorCode };
  folio_created: {
    source: FolioAnalyticsSource;
    folio_type: AnalyticsFolioType;
  };
  folio_opened: {
    source: FolioAnalyticsSource;
    folio_type: AnalyticsFolioType;
  };
  draft_milestone_reached: {
    milestone: DraftMilestone;
    word_count_bucket: WordCountBucket;
  };
  editorial_action_started: {
    action: EditorialAction;
    source: EditorialActionSource;
  };
  editorial_action_completed: {
    action: EditorialAction;
    source: EditorialActionSource;
  };
  editorial_action_failed: {
    action: EditorialAction;
    source: EditorialActionSource;
    error_code: AppErrorCode;
  };
  draft_exported: { format: DraftExportFormat };
  draft_published: { destination: DraftPublishDestination };
  dossier_completed: { mode: DossierMode };
  ai_settings_saved: {
    provider: AnalyticsAiProvider;
    feature_override_count: number;
  };
}

export type ProductEventName = keyof ProductAnalyticsEventMap;
export type ProductEventProperties<Event extends ProductEventName> =
  ProductAnalyticsEventMap[Event];
export type ProductEventPayload<Event extends ProductEventName> =
  ProductEventProperties<Event> & {
    analytics_version: typeof ANALYTICS_VERSION;
  };

/**
 * The allowlist is also a runtime privacy boundary. TypeScript rejects unknown
 * properties for object literals, while this table drops them when an object
 * has been widened or arrives from untyped JavaScript.
 */
const PRODUCT_EVENT_PROPERTY_KEYS = {
  landing_cta_clicked: ["location", "destination"],
  sign_in_started: ["method"],
  sign_in_completed: ["provider"],
  sign_in_failed: ["method", "error_code"],
  folio_created: ["source", "folio_type"],
  folio_opened: ["source", "folio_type"],
  draft_milestone_reached: ["milestone", "word_count_bucket"],
  editorial_action_started: ["action", "source"],
  editorial_action_completed: ["action", "source"],
  editorial_action_failed: ["action", "source", "error_code"],
  draft_exported: ["format"],
  draft_published: ["destination"],
  dossier_completed: ["mode"],
  ai_settings_saved: ["provider", "feature_override_count"],
} as const satisfies {
  [Event in ProductEventName]: readonly (keyof ProductAnalyticsEventMap[Event])[];
};

const SAFE_ERROR_CODES = new Set<string>(APP_ERROR_CODES);

export function buildProductEventPayload<Event extends ProductEventName>(
  event: Event,
  properties: ProductEventProperties<Event>,
): ProductEventPayload<Event> {
  const input = properties as unknown as Record<string, unknown>;
  const payload: Record<string, unknown> = {
    analytics_version: ANALYTICS_VERSION,
  };

  for (const key of PRODUCT_EVENT_PROPERTY_KEYS[event] as readonly string[]) {
    payload[key] = input[key];
  }

  // A caller using `any` must still never turn an exception message into an
  // analytics property. Only Twyne's stable, content-free error vocabulary is
  // allowed across this boundary.
  if (
    "error_code" in payload &&
    (typeof payload.error_code !== "string" ||
      !SAFE_ERROR_CODES.has(payload.error_code))
  ) {
    payload.error_code = "INTERNAL_ERROR";
  }

  return payload as unknown as ProductEventPayload<Event>;
}

export async function captureProductEvent<Event extends ProductEventName>(
  event: Event,
  properties: ProductEventProperties<Event>,
): Promise<void> {
  await capturePostHogEvent(
    event,
    buildProductEventPayload(event, properties) as unknown as Record<
      string,
      unknown
    >,
  );
}

/** Count prose words without retaining or returning any draft content. */
export function countDraftWords(htmlOrText: string): number {
  const text = htmlOrText
    .replace(/<script\b[^>]*>[\s\S]*?<\/script\s*>/gi, " ")
    .replace(/<style\b[^>]*>[\s\S]*?<\/style\s*>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;|&#160;|&#xa0;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/&quot;/gi, '"')
    .replace(/&apos;|&#39;/gi, "'")
    .replace(/&(?:#\d+|#x[\da-f]+|[a-z][\da-z]+);/gi, " ")
    .trim();

  if (!text) return 0;
  return text.split(/\s+/u).filter((token) => /[\p{L}\p{N}]/u.test(token))
    .length;
}

function normalizedWordCount(count: number): number {
  return Number.isFinite(count) ? Math.max(0, Math.floor(count)) : 0;
}

export function wordCountBucket(count: number): WordCountBucket {
  const words = normalizedWordCount(count);
  if (words === 0) return "empty";
  if (words < 100) return "1_99";
  if (words < 500) return "100_499";
  if (words < 1000) return "500_999";
  if (words < 2500) return "1000_2499";
  return "2500_plus";
}

const DRAFT_MILESTONES = [
  { count: 1, milestone: "first_edit" },
  { count: 100, milestone: "100_words" },
  { count: 500, milestone: "500_words" },
  { count: 1000, milestone: "1000_words" },
  { count: 2500, milestone: "2500_words" },
] as const satisfies readonly { count: number; milestone: DraftMilestone }[];

/** Return every milestone crossed by an upward word-count transition. */
export function crossedDraftMilestones(
  previous: number,
  current: number,
): DraftMilestone[] {
  const before = normalizedWordCount(previous);
  const after = normalizedWordCount(current);
  if (after <= before) return [];

  return DRAFT_MILESTONES.filter(
    ({ count }) => before < count && count <= after,
  ).map(({ milestone }) => milestone);
}
