121	  uri: string,
122	  name: string,
123	): Promise<PublicationRef> {
124	  const parsed = parseAtUri(uri);
125	  if (
126	    !parsed ||
127	    parsed.collection !== STANDARD_SITE_PUBLICATION_COLLECTION ||
128	    parsed.did !== repoDid(agent)
129	  ) {
130	    throw new Error(
131	      "Cached Standard.site publication does not belong to this PDS",
132	    );
133	  }
134	
135	  let current: UnknownRecord | null = null;
136	  try {
137	    const existing = await agent.com.atproto.repo.getRecord({
138	      repo: parsed.did,
139	      collection: STANDARD_SITE_PUBLICATION_COLLECTION,
140	      rkey: parsed.rkey,
141	    });
142	    current = existing.data.value as UnknownRecord;
143	  } catch {
144	    // A stale local cache is allowed to recreate its deterministic record.
145	  }
146	
147	  const url = standardSitePublicationUrl(parsed.did, parsed.rkey);
148	  await agent.com.atproto.repo.putRecord({
149	    repo: parsed.did,
150	    collection: STANDARD_SITE_PUBLICATION_COLLECTION,
151	    rkey: parsed.rkey,
152	    record: publicationRecord(current, { name, url }),
153	  });
154	
155	  const ref = { uri, name, url };
156	  await saveMetaToIdb(PUBLICATION_META_KEY, ref);
157	  return ref;
158	}
